SELECT CASE WHEN suppliers.rating >= 4.2 THEN 'high' WHEN suppliers.rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(inventory.last_restock) AS min_last_restock FROM inventory LEFT OUTER JOIN products ON inventory.product_id = products.id INNER JOIN suppliers ON products.supplier_id = suppliers.id GROUP BY CASE WHEN suppliers.rating >= 4.2 THEN 'high' WHEN suppliers.rating >= 2.2 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket
